/// <summary>
/// PaffH 15.11.21
/// display message(s) in form
/// </summary>
[Form]
public class NDXShowMessage extends FormRun
{
}

/// <summary>
/// PaffH 15.11.21
/// </summary>
public void init()
{
    super();

    if (element.args())
    {
        if (element.args() is NDXMessageFormArgs)
        {
            NDXMessageFormArgs messageFormArgs = element.args() as NDXMessageFormArgs;
            NDXControlAttributes controlAttributes1 = messageFormArgs.parmControlAttributes1();
            if (controlAttributes1.parmIsHTMLText())
            {
                HtmlViewerControl1.parmHtml(controlAttributes1.parmText());
                MessageControl.visible(false);
            }
            else
            {
                MessageControl.text(controlAttributes1.parmText());
                if (controlAttributes1.parmInitColorScheme())
                {
                    MessageControl.colorScheme(controlAttributes1.parmColorScheme());
                    MessageControl.foregroundColor(controlAttributes1.parmForegroundColor());
                    MessageControl.backgroundColor(controlAttributes1.parmBackgroundColor());
                }
                HtmlViewerControl1.visible(false);
            }
        }
        else
        {
            MessageControl.text(element.args().parm());
        }
    }
}
